INSERT INTO organizer.roles(code,name) VALUES ('editor','Pengelola konten') ON CONFLICT(code) DO NOTHING;
INSERT INTO organizer.role_permissions(role_id,permission_id) SELECT r.id,p.id FROM organizer.roles r CROSS JOIN organizer.permissions p WHERE r.code='editor' AND (p.code IN ('profile.read','media.read','media.create','templates.read','site_settings.read') OR (p.module IN ('team_members','testimonials','services') AND split_part(p.code,'.',2) IN ('read','create','update'))) ON CONFLICT(role_id,permission_id) DO NOTHING;
INSERT INTO organizer.team_members(id,name,role_title,biography,is_founder,sort_order,status) VALUES ('71000000-0000-4000-8000-000000000001','Nadia','The Visionary Founder','Setiap cerita besar berawal dari perhatian pada hal kecil. Dengan visi yang tenang dan hati yang terbuka, ia membantu setiap pasangan menikmati perjalanan menuju hari istimewa.',NOT EXISTS(SELECT 1 FROM organizer.team_members),0,'draft') ON CONFLICT DO NOTHING;
INSERT INTO organizer.team_members(id,name,role_title,biography,is_founder,sort_order,status) VALUES ('71000000-0000-4000-8000-000000000002','Arga','The Experience Shaper','Membaca suasana, menyatukan energi, dan menjaga setiap rangkaian terasa hidup. Baginya, acara yang baik meninggalkan kenangan yang terasa personal.',false,1,'draft') ON CONFLICT DO NOTHING;
INSERT INTO organizer.team_members(id,name,role_title,biography,is_founder,sort_order,status) VALUES ('71000000-0000-4000-8000-000000000003','Salsa','The Creative Spark','Mengubah percakapan sederhana menjadi ide yang berkesan. Ia merangkai warna, detail, dan suasana agar setiap perayaan punya ceritanya sendiri.',false,2,'draft') ON CONFLICT DO NOTHING;
INSERT INTO organizer.team_members(id,name,role_title,biography,is_founder,sort_order,status) VALUES ('71000000-0000-4000-8000-000000000004','Dimas','The Detail Keeper','Selangkah lebih awal untuk setiap kebutuhan. Ia menjaga waktu, koordinasi, dan detail di balik layar supaya Anda bisa hadir sepenuhnya dalam momen bahagia.',false,3,'draft') ON CONFLICT DO NOTHING;
INSERT INTO organizer.services(id,title,slug,summary,description,highlight,sort_order,status) VALUES ('72000000-0000-4000-8000-000000000001','Wedding Planner','wedding-planner','Dari ide pertama hingga detail terakhir, kami membantu menyusun perjalanan menuju hari pernikahan yang terasa personal dan terencana.','Dari ide pertama hingga detail terakhir, kami membantu menyusun perjalanan menuju hari pernikahan yang terasa personal dan terencana.','Nikmati perjalanannya. Kami mendampingi setiap langkah Anda.',0,'draft') ON CONFLICT DO NOTHING;
INSERT INTO organizer.services(id,title,slug,summary,description,highlight,sort_order,status) VALUES ('72000000-0000-4000-8000-000000000002','Wedding Organizer','wedding-organizer','Koordinasi waktu, alur acara, dan seluruh detail di hari istimewa agar Anda dapat hadir sepenuhnya dalam setiap momen.','Koordinasi waktu, alur acara, dan seluruh detail di hari istimewa agar Anda dapat hadir sepenuhnya dalam setiap momen.','Anda merayakan cinta. Kami menjaga jalannya acara.',1,'draft') ON CONFLICT DO NOTHING;
INSERT INTO organizer.services(id,title,slug,summary,description,highlight,sort_order,status) VALUES ('72000000-0000-4000-8000-000000000003','Sangjit Planner','sangjit-planner','Perayaan tradisi yang direncanakan dengan perhatian pada makna, keluarga, serta setiap rangkaian prosesi.','Perayaan tradisi yang direncanakan dengan perhatian pada makna, keluarga, serta setiap rangkaian prosesi.','Tradisi yang bermakna, detail yang terjaga.',2,'draft') ON CONFLICT DO NOTHING;
INSERT INTO organizer.services(id,title,slug,summary,description,highlight,sort_order,status) VALUES ('72000000-0000-4000-8000-000000000004','Engagement','engagement','Sebuah awal yang dirayakan bersama orang terdekat, dengan suasana dan detail yang mencerminkan cerita Anda.','Sebuah awal yang dirayakan bersama orang terdekat, dengan suasana dan detail yang mencerminkan cerita Anda.','Karena awal cerita layak dirayakan.',3,'draft') ON CONFLICT DO NOTHING;
INSERT INTO organizer.services(id,title,slug,summary,description,highlight,sort_order,status) VALUES ('72000000-0000-4000-8000-000000000005','Social Event','social-event','Pertemuan dan perayaan yang disusun dengan perhatian pada pengalaman tamu, suasana, serta momen kebersamaan.','Pertemuan dan perayaan yang disusun dengan perhatian pada pengalaman tamu, suasana, serta momen kebersamaan.','Momen sederhana, kesan yang tinggal lebih lama.',4,'draft') ON CONFLICT DO NOTHING;
INSERT INTO organizer.services(id,title,slug,summary,description,highlight,sort_order,status) VALUES ('72000000-0000-4000-8000-000000000006','Corporate Event','corporate-event','Perencanaan acara yang menyelaraskan identitas, kebutuhan, dan koordinasi agar setiap rangkaian berjalan dengan baik.','Perencanaan acara yang menyelaraskan identitas, kebutuhan, dan koordinasi agar setiap rangkaian berjalan dengan baik.','Detail yang selaras untuk pengalaman yang berkesan.',5,'draft') ON CONFLICT DO NOTHING;
INSERT INTO organizer.testimonials(id,couple_name,venue,excerpt,full_review,sort_order,status) VALUES ('73000000-0000-4000-8000-000000000001','Andi & Maya','Jakarta','Dari persiapan sampai hari acara, semuanya terasa tenang dan terarah. Kami bisa menikmati setiap momen bersama keluarga.','Tim membantu kami merapikan ide, menyusun jadwal, dan menjaga koordinasi di hari acara. Perhatian pada hal kecil membuat perayaan terasa personal. Ini adalah contoh ulasan untuk pratinjau desain.',0,'draft') ON CONFLICT DO NOTHING;
INSERT INTO organizer.testimonials(id,couple_name,venue,excerpt,full_review,sort_order,status) VALUES ('73000000-0000-4000-8000-000000000002','Raka & Putri','Bandung','Detail kecil yang kami bayangkan terwujud dengan indah. Suasananya hangat dan setiap rangkaian berjalan nyaman.','Kami membayangkan sebuah perayaan yang intim. Mulai dari alur acara hingga suasana ruang, seluruh detail tersusun selaras. Ini adalah contoh ulasan untuk pratinjau desain.',1,'draft') ON CONFLICT DO NOTHING;
INSERT INTO organizer.testimonials(id,couple_name,venue,excerpt,full_review,sort_order,status) VALUES ('73000000-0000-4000-8000-000000000003','Dion & Clara','Surabaya','Koordinasinya rapi, komunikasinya jelas, dan keluarga kami merasa didampingi sepanjang acara.','Rangkaian persiapan menjadi lebih mudah karena setiap keputusan dibahas dengan jelas. Kami bisa hadir sepenuhnya di hari istimewa tanpa sibuk memikirkan koordinasi. Ini adalah contoh ulasan untuk pratinjau desain.',2,'draft') ON CONFLICT DO NOTHING;
INSERT INTO organizer.testimonials(id,couple_name,venue,excerpt,full_review,sort_order,status) VALUES ('73000000-0000-4000-8000-000000000004','Bima & Alya','Yogyakarta','Perayaan sederhana kami terasa sangat istimewa. Setiap bagian punya sentuhan yang sesuai dengan cerita kami.','Kami menyukai pendekatan yang mendengarkan kebutuhan kami sejak awal. Susunan acara dan detail perayaan terasa dekat dengan keluarga. Ini adalah contoh ulasan untuk pratinjau desain.',3,'draft') ON CONFLICT DO NOTHING;
INSERT INTO organizer.testimonials(id,couple_name,venue,excerpt,full_review,sort_order,status) VALUES ('73000000-0000-4000-8000-000000000005','Kevin & Nara','Bali','Kami paling mengingat suasana yang hangat dan alur acara yang mengalir. Hari itu terasa begitu menyenangkan.','Dari penyambutan tamu sampai momen terakhir, semua terasa menyatu. Ada ruang bagi kami untuk menikmati waktu bersama orang-orang terdekat. Ini adalah contoh ulasan untuk pratinjau desain.',4,'draft') ON CONFLICT DO NOTHING;
INSERT INTO organizer.testimonials(id,couple_name,venue,excerpt,full_review,sort_order,status) VALUES ('73000000-0000-4000-8000-000000000006','Fajar & Livia','Semarang','Terima kasih untuk perhatian dan ketenangannya. Kami merasa didengar, dibantu, dan ditemani di setiap langkah.','Setiap persiapan dibicarakan dengan sabar dan terperinci. Ketika hari acara tiba, kami merasa siap dan bisa fokus merayakan kebersamaan. Ini adalah contoh ulasan untuk pratinjau desain.',5,'draft') ON CONFLICT DO NOTHING;
